import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_OL": 32, "BLOCK_N": 64},
        ),
    ],
    key=["OL", "OC"],
)
@triton.jit
def _conv1d_kernel(
    x_ptr,
    w_ptr,
    y_ptr,
    OL,
    OC,
    stride_xn,
    stride_xc,
    stride_wk,
    stride_wi,
    stride_wo,
    stride_yn,
    stride_yoc,
    C_IN: tl.constexpr,
    BLOCK_K: tl.constexpr,
    KERNEL_SIZE: tl.constexpr,
    STRIDE_CONV: tl.constexpr,
    DILATION: tl.constexpr,
    BLOCK_OL: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    n = tl.program_id(0)
    pid_ol = tl.program_id(1)
    pid_n = tl.program_id(2)

    ol_start = pid_ol * BLOCK_OL
    offs_ol = ol_start + tl.arange(0, BLOCK_OL)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)

    mask_ol = offs_ol < OL
    mask_n = offs_n < OC

    acc = tl.zeros((BLOCK_OL, BLOCK_N), dtype=tl.float32)

    offs_k = tl.arange(0, BLOCK_K)
    x_batch = x_ptr + n.to(tl.int64) * stride_xn

    for k in range(KERNEL_SIZE):
        in_pos = offs_ol * STRIDE_CONV + k * DILATION

        x_addrs = x_batch + offs_k[None, :].to(tl.int64) * stride_xc + in_pos[:, None]
        x_tile = tl.load(
            x_addrs, mask=mask_ol[:, None] & (offs_k[None, :] < C_IN), other=0.0
        )

        w_bp = tl.make_block_ptr(
            base=w_ptr + k * stride_wk,
            shape=(C_IN, OC),
            strides=(stride_wi, stride_wo),
            offsets=(0, pid_n * BLOCK_N),
            block_shape=(BLOCK_K, BLOCK_N),
            order=(1, 0),
        )
        w_tile = tl.load(w_bp, boundary_check=(0, 1), padding_option="zero")

        acc = tl.dot(x_tile, w_tile, acc)

    y_batch = y_ptr + n.to(tl.int64) * stride_yn
    y_addrs = y_batch + offs_n[None, :].to(tl.int64) * stride_yoc + offs_ol[:, None]
    tl.store(y_addrs, acc.to(tl.float16), mask=mask_ol[:, None] & mask_n[None, :])


class Model(nn.Module):
    def __init__(
        self, in_channels, out_channels, kernel_size, stride=1, dilation=1, bias=False
    ):
        super().__init__()
        self.conv1d = nn.Conv1d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            dilation=dilation,
            bias=bias,
        )
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size_val = kernel_size
        self.stride_val = stride
        self.dilation_val = dilation
        self._packed = False

    def _pack_weights(self):
        w = self.conv1d.weight.data
        w_kio = w.permute(2, 1, 0).contiguous()
        self.w_kio = w_kio.to("cpu", dtype=torch.float16).contiguous()
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        if x.device.type != "cpu" or x.dtype != torch.float16:
            x = x.to("cpu", dtype=torch.float16)
        if not x.is_contiguous():
            x = x.contiguous()

        N = x.shape[0]
        IC = x.shape[1]
        L = x.shape[2]
        OC = self.out_channels
        KS = self.kernel_size_val
        S = self.stride_val
        D = self.dilation_val
        OL = (L - D * (KS - 1) - 1) // S + 1

        BLOCK_K = triton.next_power_of_2(max(16, IC))

        y = torch.empty((N, OC, OL), device="cpu", dtype=torch.float16)

        grid = lambda META: (
            N,
            triton.cdiv(OL, META["BLOCK_OL"]),
            triton.cdiv(OC, META["BLOCK_N"]),
        )

        _conv1d_kernel[grid](
            x,
            self.w_kio,
            y,
            OL,
            OC,
            x.stride(0),
            x.stride(1),
            self.w_kio.stride(0),
            self.w_kio.stride(1),
            self.w_kio.stride(2),
            y.stride(0),
            y.stride(1),
            C_IN=IC,
            BLOCK_K=BLOCK_K,
            KERNEL_SIZE=KS,
            STRIDE_CONV=S,
            DILATION=D,
        )

        return y
